def parentsFromTraversals(preorder, postorder):
    pos = {v: i for i, v in enumerate(postorder)}
    parents = [-1]
    stack = [preorder[0]]
    for x in preorder[1:]:
        while pos[stack[-1]] < pos[x]:  # already left before x: not an ancestor
            stack.pop()
        parents.append(stack[-1])
        stack.append(x)
    return parents
